(root/'results.json').write_text(json.dumps(results,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
print('Recorded PHOTO-008 Pass, 228/62/63/63/63 headless regressions and byte-exact artwork save/reopen.')
